.hasFocus;  bool get _hasMaxLength => _config.maxLength != null && _config.maxLength! > 0;  bool get _hasIntrinsicError => _evaluateHasIntrinsicError();  bool get _canRequestFocus => _evaluateCanRequestFocus();  bool get _expands => _config.expands;  bool get _animateLabel =>      _config.hasFloatingLabel &&      (_effectiveFocusNode.hasFocus || editingValue.isNotEmpty);  bool get _textAlignVerticalTop =>      _config.textAlignVertical == TextAlignVertical.top;  bool get _textAlignVerticalBottom =>      _config.textAlignVertical == TextAlignVertical.bottom;  bool get _showHint => editingValue.isEmpty || _config.hasFloatingLabel;  EditableTextState? get _editableText => editableTextKey.currentState;  int get _currentLength => _effectiveController.value.text.characters.length;  String get editingValue => _effectiveController.value.text;  FocusNode get _effectiveFocusNode =>      _config.focusNode ?? (_focusNode ??= FocusNode());  MaxLengthEnforcement get _effectiveMaxLengthEnforcement =>      _evaluateMaxLengthEnforcement();  MoonTextInputConfiguration get _config => widget.textInputConfiguration;  TextEditingController get _effectiveController =>      _config.controller ?? _controller!.value;  TargetPlatform get _platform => Theme.of(context).platform;  @override  String? get restorationId => _config.restorationId;  @override  String get autofillId => _editableText!.autofillId;  @override  bool get selectionEnabled => _config.enableInteractiveSelection;  @override  TextInputConfiguration get textInputConfiguration {    final List<String>? autofillHints =        _config.autofillHints?.toList(growable: false);    final AutofillConfiguration autofillConfiguration = autofillHints != null        ? AutofillConfiguration(            uniqueIdentifier: autofillId,            autofillHints: autofillHints,            currentEditingValue: _effectiveController.value,          )        : AutofillConfiguration.disabled;