return switch ((_config.textAlignVertical, _config.textAlign)) {      (TextAlignVertical.top, TextAlign.start) => AlignmentDirectional.topStart,      (TextAlignVertical.top, TextAlign.center) =>        AlignmentDirectional.topCenter,      (TextAlignVertical.top, TextAlign.end) => AlignmentDirectional.topEnd,      (TextAlignVertical.center, TextAlign.start) =>        AlignmentDirectional.centerStart,      (TextAlignVertical.center, TextAlign.center) =>        AlignmentDirectional.center,      (TextAlignVertical.center, TextAlign.end) =>        AlignmentDirectional.centerEnd,      (TextAlignVertical.bottom, TextAlign.start) =>        AlignmentDirectional.bottomStart,      (TextAlignVertical.bottom, TextAlign.center) =>        AlignmentDirectional.bottomCenter,      (TextAlignVertical.bottom, TextAlign.end) =>        AlignmentDirectional.bottomEnd,      _ => AlignmentDirectional.centerStart,    };  }  @override  void autofill(TextEditingValue newEditingValue) =>      _editableText!.autofill(newEditingValue);  @override  void initState() {    super.initState();    if (_config.controller == null) {      _createLocalController(        _config.initialValue != null            ? TextEditingValue(text: _config.initialValue!)            : null,      );    }    _mixStateController = MixWidgetStateController();    _selectionGestureDetectorBuilder =        _MoonTextInputSelectionGestureDetectorBuilder(state: this);    _effectiveFocusNode.canRequestFocus = _config.canRequestFocus && _isEnabled;    _effectiveFocusNode.addListener(_handleFocusChanged);    _inputContainerFocusNode = FocusNode(skipTraversal: true);  }  @override  void restoreState(RestorationBucket? oldBucket, bool initialRestore) {    if (_controller != null) _registerController();  }  @override  void didChangeDependencies() {    super.didChangeDependencies();    _effectiveFocusNode.canRequestFocus = _canRequestFocus;  }  @override  void didUpdateWidget(MoonRawTextInput oldWidget) {    super.didUpdateWidget(oldWidget);    final MoonTextInputConfiguration oldConfiguration =        oldWidget.textInputConfiguration;    if (_config.controller == null && oldConfiguration.controller != null) {      _createLocalController(oldConfiguration.controller!.value);    } else if (_config.controller != null &&        oldConfiguration.controller == null) {      unregisterFromRestoration(_controller!);      _controller!.dispose();      _controller = null;    }    if (_config.focusNode != oldConfiguration.focusNode) {      (oldConfiguration.focusNode ?? _focusNode)          ?.removeListener(_handleFocusChanged);      (_config.focusNode ?? _focusNode)?.addListener(_handleFocusChanged);    }    _effectiveFocusNode.canRequestFocus = _canRequestFocus;    if (_hasFocus &&        _isEnabled &&        _effectiveController.selection.isCollapsed &&        _config.readOnly != oldConfiguration.readOnly) {      _showSelectionHandles = !_config.readOnly;    }    if (_hasFocus && _isEnabled) {      _mixStateController.selected = true;    }    if (oldConfiguration.errorText != _config.errorText) {      _mixStateController.error = _hasError;    }  }  @override  void dispose() {    _effectiveFocusNode.removeListener(_handleFocusChanged);    _focusNode?.dispose();    _inputContainerFocusNode.dispose();    _controller?.dispose();    _mixStateController.dispose();    super.dispose();  }  @override  Widget build(BuildContext context) {    assert(debugCheckHasMaterial(context));    assert(debugCheckHasMaterialLocalizations(context));    assert(debugCheckHasDirectionality(context));    assert(      !(_config.style != null &&          _config.style!.inherit == false &&          (_config.style!.fontSize == null ||              _config.style!.textBaseline == null)),      "Inherit false style must supply fontSize and textBaseline.",    );    final FocusNode focusNode = _effectiveFocusNode;    final Duration effectiveTransitionDuration =        _config.transitionDuration ?? const Duration(milliseconds: 200);    final Curve effectiveTransitionCurve =        _config.transitionCurve ?? Curves.easeInOutCubic;    final List<TextInputFormatter> formatters = <TextInputFormatter>[      ...?_config.inputFormatters,      if (_hasMaxLength)        LengthLimitingTextInputFormatter(          _config.maxLength,          maxLengthEnforcement: _effectiveMaxLengthEnforcement,        ),    ];    // Disables configuration if unset; otherwise, applies platform-specific    // misspelling styles unless overridden.    final SpellCheckConfiguration spellCheckConfiguration =        defaultTargetPlatform == TargetPlatform.iOS ||                defaultTargetPlatform == TargetPlatform.macOS            ? CupertinoTextField.inferIOSSpellCheckConfiguration(                _config.spellCheckConfiguration,              )            : TextField.inferAndroidSpellCheckConfiguration(                _config.spellCheckConfiguration,              );    // Semantics value length.    final int? semanticsMaxValueLength =        (_effectiveMaxLengthEnforcement != MaxLengthEnforcement.none &&                _hasMaxLength)            ? _config.maxLength            : null;    // Platform specific parameters.    final Color cursorColor = _hasError        ? _config.cursorErrorColor ?? Colors.red        : _config.cursorColor ?? Colors.black;    final double devicePixelRatio = MediaQuery.devicePixelRatioOf(context);    bool paintCursorAboveText = false;    bool? cursorOpacityAnimates = _config.cursorOpacityAnimates;    Color? autocorrectionTextRectColor;    Color? selectionColor = DefaultSelectionStyle.of(context).selectionColor;    Offset? cursorOffset;    Radius? cursorRadius = _config.cursorRadius;    VoidCallback? handleDidGainAccessibilityFocus;    TextSelectionControls? textSelectionControls = _config.selectionControls;    switch (_platform) {      case TargetPlatform.iOS:      case TargetPlatform.macOS:        final cupertinoTheme = CupertinoTheme.of(context);        forcePressEnabled = defaultTargetPlatform == TargetPlatform.iOS;        textSelectionControls ??= (defaultTargetPlatform == TargetPlatform.iOS)            ? cupertinoTextSelectionHandleControls            : cupertinoDesktopTextSelectionHandleControls;        paintCursorAboveText = true;        cursorOpacityAnimates ??= defaultTargetPlatform == TargetPlatform.iOS;        selectionColor ??= cupertinoTheme.primaryColor.withOpacity(0.40);        cursorRadius ??= const Radius.circular(2.0);        cursorOffset = Offset(iOSHorizontalOffset / devicePixelRatio, 0);        if (defaultTargetPlatform == TargetPlatform.iOS) {          autocorrectionTextRectColor = selectionColor;        }        if (defaultTargetPlatform == TargetPlatform.macOS) {          handleDidGainAccessibilityFocus = () {            if (!_hasFocus && _effectiveFocusNode.canRequestFocus) {              // Auto-activates MoonTextInput on accessibility focus.              _effectiveFocusNode.requestFocus();            }          };        }      case TargetPlatform.android:      case TargetPlatform.fuchsia:      case TargetPlatform.linux:      case TargetPlatform.windows:        forcePressEnabled = false;        cursorOpacityAnimates ??= false;        selectionColor ??=            Theme.of(context).colorScheme.primary.withOpacity(0.40);        textSelectionControls ??=            (defaultTargetPlatform == TargetPlatform.android ||                    defaultTargetPlatform == TargetPlatform.fuchsia)                ? materialTextSelectionHandleControls                : desktopTextSelectionHandleControls;        if (defaultTargetPlatform == TargetPlatform.windows) {          handleDidGainAccessibilityFocus = () {            // Accessibility focus automatically activates MoonTextInput.            if (!_hasFocus && _effectiveFocusNode.canRequestFocus) {       