teCommand,          onChanged: _config.onChanged,          onEditingComplete: _config.onEditingComplete,          onSelectionChanged: _handleSelectionChanged,          onSelectionHandleTapped: _handleSelectionHandleTapped,          onSubmitted: _config.onSubmitted,          onTapOutside: _config.onTapOutside,          paintCursorAboveText: paintCursorAboveText,          readOnly: _config.readOnly || !_isEnabled,          rendererIgnoresPointer: true,          restorationId: "editable",          scribbleEnabled: _config.scribbleEnabled,          scrollController: _config.scrollController,          scrollPadding: _config.scrollPadding,          scrollPhysics: _config.scrollPhysics,          selectionColor: focusNode.hasFocus ? selectionColor : null,          selectionControls: selectionEnabled ? textSelectionControls : null,          selectionHeightStyle: _config.selectionHeightStyle,          selectionWidthStyle: _config.selectionWidthStyle,          showCursor: _config.showCursor,          showSelectionHandles: _showSelectionHandles,          smartDashesType: _config.smartDashesType,          smartQuotesType: _config.smartQuotesType,          spellCheckConfiguration: spellCheckConfiguration,          strutStyle: _config.strutStyle,          style: _config.style ?? const TextStyle(),          textAlign: _config.textAlign,          textCapitalization: _config.textCapitalization,          textDirection: _config.textDirection,          textInputAction: _config.textInputAction,          undoController: _config.undoController,        ),      ),    );    child = AnimatedBuilder(      animation: Listenable.merge(        <Listenable>[focusNode, _effectiveController],      ),      builder: (BuildContext context, Widget? child) {        final effectiveAlignment =            AlignmentDirectional.topStart.resolve(Directionality.of(context));        final BoxSpec? inputStyleBoxSpec = _config.inputStyle            ?.of(context)            .resolvableOf<BoxSpec, BoxSpecAttribute>();        final double? height = inputStyleBoxSpec?.height;        final EdgeInsetsGeometry effectivePadding =            inputStyleBoxSpec?.padding ?? EdgeInsets.zero;        final EdgeInsets resolvedPadding =            effectivePadding.resolve(Directionality.of(context));        final Style defaultInputStyle = Style(          $box.constraints(            minHeight: height ?? 40,            maxHeight: height ?? (_expands ? double.infinity : 40),          ),          $flex.crossAxisAlignment(            _expands ? CrossAxisAlignment.center : CrossAxisAlignment.stretch,          ),        );        return ExcludeFocusTraversal(          excluding: !_isEnabled,          child: Interactable(            enabled: _isEnabled,            controller: _mixStateController,            focusNode: _inputContainerFocusNode,            mouseCursor: _config.mouseCursor ?? SystemMouseCursors.text,            child: Box(              style: defaultInputStyle                  .merge(_config.inputStyle)                  .add($box.padding.vertical(0)),              child: StyledRow(                inherit: true,                children: [                  if (_config.leading != null) _config.leading!,                  Expanded(                    child: Stack(                      children: [                        Align(                          alignment: _getTextVerticalAlignment(),                          child: Padding(                            padding: EdgeInsets.only(                              top: resolvedPadding.top +                                  _config.inputTextVerticalOffsetValue +                                  (_expands || _textAlignVerticalTop ? 2 : 0),                              bottom: resolvedPadding.bottom +                                  (_expands || _textAlignVerticalBottom                                      ? 2                                      : 0),  