{  _MoonTextInputSelectionGestureDetectorBuilder({    required _MoonRawTextInputState state,  })  : _state = state,        super(delegate: state);  final _MoonRawTextInputState _state;  @override  bool get onUserTapAlwaysCalled => _state._config.onTapAlwaysCalled;  @override  void onUserTap() => _state._config.onTap?.call();  @override  void onForcePressEnd(ForcePressDetails details) {}  @override  void onForcePressStart(ForcePressDetails details) {    super.onForcePressStart(details);    if (delegate.selectionEnabled && shouldShowSelectionToolbar) {      editableText.showToolbar();    }  }  @override  void onSingleTapUp(TapDragUpDetails details) {    super.onSingleTapUp(details);    _state._requestKeyboard();  }  @override  void onSingleLongTapStart(LongPressStartDetails details) {    super.onSingleLongTapStart(details);    final TargetPlatform platform = Theme.of(_state.context).platform;    final bool iOsOrMacOs =        platform == TargetPlatform.iOS || platform == TargetPlatform.macOS;    if (delegate.selectionEnabled && iOsOrMacOs) {      Feedback.forLongPress(_state.context);    }  }}